#include <list>
#include <utility>
#include <vector>

class MyHashMap {
  std::vector<std::list<std::pair<int, int>>> buckets_;
  size_t size_ = 0;
  static size_t idx(int key, size_t n) {           // multiplicative hash spreads clustered keys
    return static_cast<size_t>(static_cast<unsigned>(key)) * 2654435761u % n;
  }
  void rehash() {
    std::vector<std::list<std::pair<int, int>>> nb(buckets_.size() * 2);
    for (auto& b : buckets_)
      for (auto& kv : b) nb[idx(kv.first, nb.size())].push_back(kv);
    buckets_.swap(nb);
  }
public:
  MyHashMap() : buckets_(16) {}
  void put(int key, int value) {
    auto& b = buckets_[idx(key, buckets_.size())];
    for (auto& kv : b)
      if (kv.first == key) { kv.second = value; return; }
    b.emplace_back(key, value);
    if (++size_ > buckets_.size() * 3 / 4) rehash();   // keep load factor <= 0.75
  }
  int get(int key) const {
    for (auto& kv : buckets_[idx(key, buckets_.size())])
      if (kv.first == key) return kv.second;
    return -1;
  }
  void remove(int key) {
    auto& b = buckets_[idx(key, buckets_.size())];
    for (auto it = b.begin(); it != b.end(); ++it)
      if (it->first == key) { b.erase(it); --size_; return; }
  }
};

