#include <random>
#include <vector>

class Solution {
  const std::vector<int>& nums_;          // O(1) extra memory: no index map
  std::mt19937 rng_{std::random_device{}()};
public:
  explicit Solution(const std::vector<int>& nums) : nums_(nums) {}

  // Reservoir sampling with k = 1: the c-th match replaces the answer with probability 1/c.
  int pick(int target) {
    int chosen = -1, count = 0;
    for (int i = 0; i < (int)nums_.size(); ++i) {
      if (nums_[i] != target) continue;
      ++count;
      if (std::uniform_int_distribution<int>(1, count)(rng_) == 1) chosen = i;
    }
    return chosen;
  }
};

