// Points are distinct, integer coordinates. O(n^2 log n) with an ordered map.
int maxPoints(const std::vector<std::vector<int>>& pts) {
  const int n = pts.size();
  if (n <= 2) return n;
  int best = 0;
  for (int i = 0; i < n; ++i) {
    std::map<std::pair<int, int>, int> slopes;   // reduced direction (dy, dx) -> count
    for (int j = i + 1; j < n; ++j) {            // lines through i that use later points
      int dx = pts[j][0] - pts[i][0], dy = pts[j][1] - pts[i][1];
      int g = std::gcd(dx, dy);                  // exact: no floating-point slopes
      dx /= g; dy /= g;
      if (dx < 0 || (dx == 0 && dy < 0)) { dx = -dx; dy = -dy; }   // one canonical sign
      best = std::max(best, ++slopes[{dy, dx}]);
    }
  }
  return best + 1;                               // + point i itself
}

std::vector<int> twoSum(const std::vector<int>& nums, int target) {
    std::unordered_map<int, int> seen;  // value -> index
    seen.reserve(nums.size());
    for (int i = 0; i < (int)nums.size(); i++) {
        long long need = (long long)target - nums[i];  // no int overflow
        if (need >= INT_MIN && need <= INT_MAX) {
            auto it = seen.find((int)need);
            if (it != seen.end()) return {it->second, i};
        }
        seen[nums[i]] = i;  // insert AFTER the lookup
    }
    return {};
}

