from collections import Counter

def frequency_sort(s):
    cnt = Counter(s)
    buckets = [[] for _ in range(len(s) + 1)]   # buckets[f] = chars seen f times
    for ch, f in cnt.items():
        buckets[f].append(ch)
    out = []
    for f in range(len(s), 0, -1):
        for ch in buckets[f]:
            out.append(ch * f)
    return ''.join(out)

