std::vector<int> majorityElement(const std::vector<int>& nums) {
    int c1 = 0, c2 = 1, n1 = 0, n2 = 0;   // c1 != c2 from the start
    for (int x : nums) {
        if (x == c1) ++n1;
        else if (x == c2) ++n2;
        else if (n1 == 0) { c1 = x; n1 = 1; }
        else if (n2 == 0) { c2 = x; n2 = 1; }
        else { --n1; --n2; }
    }
    n1 = n2 = 0;
    for (int x : nums) {
        if (x == c1) ++n1;
        else if (x == c2) ++n2;
    }
    std::vector<int> res;
    int lim = static_cast<int>(nums.size()) / 3;
    if (n1 > lim) res.push_back(c1);
    if (n2 > lim) res.push_back(c2);
    return res;
}

