std::vector<int> findErrorNums(std::vector<int> nums) {
    int dup = -1, miss = -1;
    for (int x : nums) {
        int v = std::abs(x);
        if (nums[v - 1] < 0) dup = v;
        else nums[v - 1] = -nums[v - 1];
