bool rotateString(const std::string& s, const std::string& goal) {
    if (s.size() != goal.size()) return false;
    const int m = goal.size();
    if (m == 0) return true;
    std::vector<int> pi(m, 0);                 // KMP prefix function of goal
    for (int i = 1; i < m; ++i) {
        int k = pi[i - 1];
        while (k > 0 && goal[i] != goal[k]) k = pi[k - 1];
        if (goal[i] == goal[k]) ++k;
        pi[i] = k;
    }
    const std::string t = s + s;
    int k = 0;
    for (char c : t) {
        while (k > 0 && c != goal[k]) k = pi[k - 1];
        if (c == goal[k]) ++k;
        if (k == m) return true;
    }
    return false;
}

