std::string shortestPalindrome(const std::string& s) {
    const std::string r(s.rbegin(), s.rend());
    const std::string t = s + '#' + r;
    std::vector<int> pi(t.size(), 0);
    for (int i = 1; i < (int)t.size(); ++i) {
        int k = pi[i - 1];
        while (k > 0 && t[i] != t[k]) k = pi[k - 1];
        if (t[i] == t[k]) ++k;
        pi[i] = k;
    }
    const int L = pi.back();          // longest palindromic prefix of s
    return r.substr(0, s.size() - L) + s;
}

